package cn.fuzhu.toolkit.modules;
import cn.fuzhu.toolkit.FuzhuToolkitPlugin; import cn.fuzhu.toolkit.module.AbstractModule; import org.bukkit.*; import org.bukkit.command.*; import org.bukkit.entity.Player; import java.util.*;
public class BlockSearchModule extends AbstractModule { public BlockSearchModule(FuzhuToolkitPlugin p){super(p);config=p.moduleConfig(id());} public String id(){return "BlockSearch";} public String description(){return "搜索附近方块并显示坐标";} public boolean handle(CommandSender s,String l,String[] a){Player p=ModuleUtil.player(plugin,s);if(p==null)return true;if(a.length<1){plugin.msg(s,"&e用法: /bs <方块名> [半径]");return true;} Material mat=Material.matchMaterial(a[0]);if(mat==null||!mat.isBlock()){plugin.msg(s,"&c未知方块: "+a[0]);return true;}int r=plugin.getConfig().getInt("search-default-radius",100);if(a.length>1)try{r=Math.min(plugin.getConfig().getInt("search-max-radius",300),Math.max(1,Integer.parseInt(a[1])));}catch(Exception ignored){}Location o=p.getLocation();List<String> found=new ArrayList<>();for(int x=o.getBlockX()-r;x<=o.getBlockX()+r;x+=1)for(int y=Math.max(p.getWorld().getMinHeight(),o.getBlockY()-r);y<=Math.min(p.getWorld().getMaxHeight(),o.getBlockY()+r);y++)for(int z=o.getBlockZ()-r;z<=o.getBlockZ()+r;z++)if(p.getWorld().getBlockAt(x,y,z).getType()==mat){found.add("&7("+x+", "+y+", "+z+")");if(found.size()>=100){x=o.getBlockX()+r+1;break;}}plugin.msg(s,"&b搜索 &f"+mat+" &b完成，共 &f"+found.size()+" &b个（最多显示100个）");found.forEach(v->plugin.msg(s,v));return true;} }
